function saveEvidence(){const type=family();if(type==='surface'&&(!revealed||!trialGuess))return toast('先選預測並顯示光路，再保存結果。');if(!LabFlow.canSave(state.evidence))return toast('證據小卡最多保留 20 張。請先刪除不需要的小卡，再儲存新結果。');if(type==='surface'&&currentEvidence('surface').some(e=>e.config.angle===state.config.angle&&e.config.medium===state.config.medium))return toast('這個測試條件已有小卡。調整角度或材料，再儲存不同的結果。');const c={...state.config},result=type==='surface'?Optics.surface(c.angle,c.medium):Optics.design(c);const id='E'+String(state.nextId++).padStart(2,'0');const e={id,type,config:c,result:type==='surface'?result:type==='color'?{color:c.color,shape:c.shape,rays:Optics.colorRays(c).map(r=>({n:r.n,through:r.through,exitAtX910:r.targetY??null}))}:{hit:result.hit,through:result.through,targetY:result.targetY,tir:result.tir},guess:type==='surface'?trialGuess:'',time:new Date().toISOString()};state.evidence.push(e);state.selected=[...state.selected.filter(x=>state.evidence.find(y=>y.id===x)?.type===type),id].slice(-2);event('evidence',`保存證據 ${id}：${type==='surface'?names[c.medium]+'、'+c.angle+'°':names[c.shape]+'、方向 '+c.angle+'°、高度 '+c.y}`);coachMessage='';coachRefs='';render();toast('已保存證據 '+id+'，可以比較或重現。');}
function restore(id){const e=state.evidence.find(x=>x.id===id);if(!e)return;state.experimentConfigs[state.configMode]={...state.config};state.configMode=e.type;state.config={...e.config};revealed=true;trialGuess=e.guess||'';state.stage=e.type==='surface'?1:e.type==='design'?3:4;event('restore','重現證據 '+id);go(e.type==='surface'?'lab':e.type==='design'?'design':'colors');toast('已重現證據 '+id);}
function hint(explicit=false,q=''){const t=family();let text=defaultHint(),es=currentEvidence(t).slice(-2),refs=es.length?es.map(e=>e.id).join('、'):'目前任務（尚無保存證據）';if(explicit){text=t==='surface'?'具體做法：先選水與 35°，預測、顯示並保存。保持水不變，把角度改成 0°，再保存。把兩張卡並排，比較交界前後的方向。':t==='design'?'先選長方形積木，把方向設為 0°，光源高度與目標相同，看看光能否通過。成功後換三角形，預測需要怎樣調整。':'先用三稜鏡、方向 0°、高度 210 保存白光，再只換紅光並保存。比較離開玻璃後的顏色。';}
 if(q){if(/一定|不.*彎|轉彎/.test(q)&&t==='surface')text=defaultHint();else if(/吸管|魚|眼睛|硬幣/.test(q))text='物體反射的光進入眼睛，我們才看見它。光跨越水面時路徑可能改變。這個模型能檢查光路，但不能完整呈現魚的視野；可以先比較空氣到水與垂直入射的情況。';else if(/顏色|彩虹|白光/.test(q))text='你可以先做「顏色偵探」：保持三稜鏡與照射條件相同，只把白光換成紅光。記下結果，再看玻璃是否會替光上色。';else if(/放大|鏡/.test(q))text='可以到「設計光路」的進階挑戰，調整玻璃曲度，比較樹看起來的大小；也可以到「好奇再出發」做放大鏡的實體觀察。';else text='這個問題超出目前預設引導可判讀的範圍。我先幫你保留；可以到「好奇再出發」把它變成待師生一起查證的問題。你也可以先問光路、吸管或色光。';}
 return {text,refs};}
function setCoach(text,refs,mode='預設引導',q=''){coachMessage=text;coachRefs='依據：'+refs;coachMode=mode;state.hints.push({text,refs,mode,question:q,time:new Date().toISOString()});event('hint',mode+'：'+(q?'回應「'+q+'」':'提供下一步提示'));if($('#coach-response'))$('#coach-response').hidden=false;if($('#coach-message')){$('#coach-message').textContent=text;$('#coach-evidence').textContent=coachRefs;$('#coach-mode').textContent=mode;}}
async function ask(){const q=$('#question')?.value.trim();if(!q||busy)return;if(q.length>300)return toast('問題請在 300 字內。');busy=true;const turnEpoch=epoch,backup=hint(false,q),payload={question:q,task:family(),hypothesis:state.hypothesis,config:state.config,evidence:currentEvidence().slice(-6).map(({id,config,result,guess})=>({id,config,result,guess})),previousHints:state.hints.slice(-2).map(h=>h.text)};if($('#coach-response'))$('#coach-response').hidden=false;if($('#coach-message'))$('#coach-message').textContent='正在根據你的問題和實驗找線索…';try{if(location.protocol==='file:')throw Error('local');const res=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error('offline');const data=await res.json();if(data.mode!=='ai'||typeof data.text!=='string'||!Array.isArray(data.evidenceIds)||!data.evidenceIds.every(id=>payload.evidence.some(e=>e.id===id)))throw Error('invalid');if(epoch===turnEpoch)setCoach(data.text,data.evidenceIds.join('、')||'目前任務教材','AI 即時引導',q);else {state.hints.push({text:data.text,refs:data.evidenceIds.join('、'),mode:'AI 即時引導',question:q,time:new Date().toISOString()});persist();}}catch{if(epoch===turnEpoch)setCoach(backup.text,backup.refs,'預設引導',q);}finally{busy=false;}}
function planQuestion(q){if(/顏色|彩虹|白光|紅光/.test(q))return {status:'ready',plan:'保持三稜鏡、方向、高度相同，比較白光與單色光，完成顏色發現卡。約 15 分鐘。',link:'colors'};if(/路|積木|到達|方向/.test(q))return {status:'ready',plan:'選擇一個目標，保存兩種積木的命中配置，說明光源需要怎麼調整。約 10 分鐘。',link:'design'};return {status:'pending',plan:'先寫出想改變的條件與想觀察的結果，帶給老師一起確認。本模型尚不能完整驗證這個問題。',link:null};}
function saveQuestion(q){const plan=planQuestion(q);state.questions.push({text:q,...plan,time:new Date().toISOString()});event('question','保存我的問題：'+q);render();$('#question-plan').innerHTML=`<div class="feedback"><strong>${plan.status==='ready'?'找到一個可以做的小任務':'已加入待師生查證清單'}</strong><p>${plan.plan}</p>${plan.link?`<a class="btn primary" href="#${plan.link}">進入這個任務</a>`:''}</div>`;}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();$('#close-modal').onclick=()=>$('#modal').close();}
function exportRecord(){const data=JSON.stringify({...state,exportedAt:new Date().toISOString(),notice:'本機原型學習紀錄，非正式成績'},null,2),blob=new Blob([data],{type:'application/json'}),u=URL.createObjectURL(blob);modal(`<h2>匯出我的學習紀錄</h2><p>下載 JSON 檔保存完整資料。若目前瀏覽器未開啟下載，也可以複製下方內容。</p><div class="actions"><a class="btn primary" href="${u}" download="光的旅行_學習紀錄.json">下載 JSON 檔</a><button class="btn" id="copy-record">複製紀錄內容</button></div><label for="export-json" class="section-gap">完整學習紀錄（可選取複製）</label><textarea id="export-json" readonly style="min-height:240px;font-family:monospace;font-size:14px">${esc(data)}</textarea>`);$('#copy-record').onclick=async()=>{try{await navigator.clipboard.writeText(data);toast('已複製學習紀錄。');}catch{$('#export-json').select();toast('已選取內容，請按 Ctrl+C 複製。');}};setTimeout(()=>URL.revokeObjectURL(u),600000);}

function action(a){if(a==='teacher-report'){downloadTeacherReport();return;}if(a==='edit-reflection'){state.explanationEditing=true;state.explanationDraft=state.explanation;persist();render();$('#reflection')?.focus();return;}if(a==='cancel-reflection'){state.explanationEditing=false;state.explanationDraft=null;persist();render();return;}if(a==='undo-evidence'){if(!LabFlow.canSave(state.evidence))return toast('證據小卡已達 20 張，請先刪除一張，再復原。');const e=state.trash.pop();if(e){state.evidence.push(e);state.evidence.sort((a,b)=>a.id.localeCompare(b.id));persist();render();toast('已復原證據 '+e.id);}return;}if(a==='reveal'){if(!trialGuess)return toast('先選一個預測。');revealed=true;event('reveal',`檢查預測「${trialGuess}」：${names[state.config.medium]}、${state.config.angle}°`);updateScene();}else if(a==='save-evidence')saveEvidence();else if(a==='to-compare'){if(!LabFlow.canCompare(state.evidence))return toast('至少需要 2 張不同測試結果的證據小卡。');state.stage=2;go('compare');}else if(a==='to-lab'){state.stage=1;go('lab');}else if(a==='notebook')go('notebook');else if(a==='reset-config'){state.config={...fresh().config,angle:family()==='surface'?35:0,shape:family()==='color'?'none':'prism'};revealed=false;trialGuess='';render();}else if(a==='hint'||a==='explain'){const h=hint(a==='explain');setCoach(h.text,h.refs);}else if(a==='ask')ask();else if(a==='export')exportRecord();else if(a==='print')window.print();else if(a==='lens')modal('<span class="chip orange">實體活動腳本 · 可搭配設計光路頁的透鏡活動</span><h2 class="section-gap">小字，什麼時候看起來更大？</h2><p>材料：放大鏡、印有小字的紙、尺。只看紙上文字，不看太陽或強光。</p><ol class="hint-list"><li>把紙放在桌面，選一個字。</li><li>先猜放大鏡離紙越遠，字會一直越大嗎？</li><li>保持紙與觀察位置，選三個距離；分別畫下清楚程度與字的大小。</li><li>比較結果：有沒有不符合原先猜想的情況？</li></ol><p>完成後可把問題帶回「好奇再出發」記錄。正式成像教學需由老師協助。</p>');else if(a==='reset'){modal('<h2>重設這台裝置的演示紀錄？</h2><p>會清除猜想、證據、作品、測驗及教師回饋。建議先匯出保存。</p><div class="actions"><button class="btn" id="export-before-reset">先匯出</button><button class="btn danger" id="confirm-reset">清除並重新開始</button></div>');$('#export-before-reset').onclick=exportRecord;$('#confirm-reset').onclick=()=>{state=fresh();state.aiAnalyses={};analysisErrors.clear();coachMessage='';coachRefs='';revealed=false;trialGuess='';persist();$('#modal').close();go('lab');toast('已重設，開始一段新的探索。');};}}
window.addEventListener('hashchange',()=>{coachMessage='';coachRefs='';coachMode='預設引導';render();});window.addEventListener('storage',e=>{if(e.key===KEY)toast('另一個頁面更新了紀錄，重新整理可載入。');});
