if(document.modelContext?.registerTool){const ac=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:ac.signal})).catch(()=>{});}catch{}};register({name:'read_learning_progress',title:'讀取探索進度',description:'Read this device’s saved evidence counts and milestones without changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({evidenceCount:state.evidence.length,milestones:completed(),questionCount:state.questions.length})});register({name:'configure_light_experiment',title:'調整光路實驗',description:'Stage the surface experiment angle and medium; does not reveal results or save evidence.',inputSchema:{type:'object',properties:{angle:{type:'number',minimum:0,maximum:70},medium:{type:'string',enum:['water','glass','air']}},required:['angle','medium'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.angle!=='number'||!Number.isFinite(input.angle)||input.angle<0||input.angle>70||!['water','glass','air'].includes(input.medium))throw Error('Invalid experiment configuration');state.experimentConfigs[state.configMode]={...state.config};state.configMode='surface';state.config={...fresh().config,...state.experimentConfigs.surface,angle:input.angle,medium:input.medium};state.stage=1;trialGuess='';revealed=false;history.replaceState(null,'','#lab');render();return {angle:state.config.angle,medium:state.config.medium,revealed:false};}});window.addEventListener('pagehide',()=>ac.abort(),{once:true});}
render();
